import { z } from 'zod';
// OpenAPI Overlay Specification v1.1.0: https://spec.openapis.org/overlay/v1.1.0.html
const SUPPORTED_OVERLAY_VERSION_PATTERN = /^1\.[01](\.\d+)?$/;
const specificationExtensionKey = /^x-/;
const rejectUnknownKeys = (knownKeys) => {
    return (value, ctx) => {
        for (const key of Object.keys(value)) {
            if (!knownKeys.includes(key) && !specificationExtensionKey.test(key)) {
                ctx.addIssue({
                    code: z.ZodIssueCode.custom,
                    message: `Unknown field "${key}". Only specification extensions (fields starting with "x-") are allowed in addition to the fixed fields.`,
                });
            }
        }
    };
};
export const overlayInfoSchema = z
    .object({
    title: z.string({
        required_error: 'The Overlay "info.title" field is required',
    }),
    version: z.string({
        required_error: 'The Overlay "info.version" field is required',
    }),
    description: z.string().optional(),
})
    .passthrough()
    .superRefine(rejectUnknownKeys(['title', 'version', 'description']));
export const overlayActionSchema = z
    .object({
    target: z
        .string({ required_error: 'Each Overlay action requires a "target" JSONPath expression' })
        .trim()
        .nonempty('Each Overlay action requires a non-empty "target" JSONPath expression'),
    description: z.string().optional(),
    update: z.unknown().optional(),
    copy: z.string().trim().nonempty().optional(),
    remove: z.boolean().optional(),
})
    .passthrough()
    .superRefine(rejectUnknownKeys(['target', 'description', 'update', 'copy', 'remove']))
    .superRefine((action, ctx) => {
    if (action.update !== undefined && action.copy !== undefined) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: `Action targeting "${action.target}" sets both "update" and "copy". Use only one modifier per action.`,
        });
    }
    if (action.update === undefined && action.copy === undefined && action.remove !== true) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: `Action targeting "${action.target}" has no effect. Set "update", "copy", or "remove: true".`,
        });
    }
});
export const overlayDocumentSchema = z
    .object({
    overlay: z
        .string({
        required_error: 'The Overlay "overlay" version field is required',
        invalid_type_error: 'The Overlay "overlay" version field must be a string, e.g. "1.1.0"',
    })
        .regex(SUPPORTED_OVERLAY_VERSION_PATTERN, 'Unsupported Overlay Specification version. Supported versions are 1.0.x and 1.1.x'),
    info: overlayInfoSchema,
    extends: z.string().optional(),
    actions: z
        .array(overlayActionSchema)
        .min(1, 'The Overlay "actions" array must contain at least one action'),
})
    .passthrough()
    .superRefine(rejectUnknownKeys(['overlay', 'info', 'extends', 'actions']))
    .superRefine((document, ctx) => {
    // The "copy" modifier was introduced in Overlay Specification 1.1.0.
    if (!document.overlay.startsWith('1.0'))
        return;
    document.actions.forEach((action, index) => {
        if (action.copy !== undefined) {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                path: ['actions', index, 'copy'],
                message: 'The "copy" modifier requires Overlay Specification 1.1.0 or later. Declare overlay: "1.1.0" to use copy.',
            });
        }
    });
});
/**
 * Routes discovery: any non-array object with a top-level `overlay` field counts, so
 * malformed version values surface validation errors instead of being ignored.
 */
export function isOverlayDocument(value) {
    return typeof value === 'object' && value !== null && !Array.isArray(value) && 'overlay' in value;
}
/** Validates a parsed value against the Overlay schema, throwing a readable error. */
export function parseOverlayDocument(value) {
    const result = overlayDocumentSchema.safeParse(value);
    if (!result.success) {
        const details = result.error.issues
            .map((issue) => {
            const path = issue.path.length > 0 ? `${issue.path.join('.')}: ` : '';
            return `${path}${issue.message}`;
        })
            .join('; ');
        throw new Error(`Invalid OpenAPI Overlay document: ${details}`);
    }
    return result.data;
}
/** Non-throwing variant of {@link parseOverlayDocument}. */
export function safeParseOverlayDocument(value) {
    try {
        return { success: true, data: parseOverlayDocument(value) };
    }
    catch (error) {
        return {
            success: false,
            errorMessage: error instanceof Error ? error.message : String(error),
        };
    }
}
